        path: PathBuf::from("pyproject.toml"),
        role: ManifestRole::Canonical,
        format: ManifestFormat::PyprojectToml,
    };
    let ctx = OpenContext {
        workspace_root: dir.path(),
        cargo_workspace: None,
        npm_workspace_kind: None,
